import { Injectable, inject } from '@angular/core';
import { SupabaseClient } from '@supabase/supabase-js';
import { Database } from 'supabase/types/supabase';

@Injectable({
  providedIn: 'root',
})
export class StorageService {
  private readonly supabaseClient = inject(SupabaseClient<Database>);

  async download(bucket: StorageBucket, path: string) {
    const { data, error } = await this.supabaseClient.storage
      .from(bucket)
      .download(path);

    if (error) {
      throw error;
    }

    return data;
  }

  async remove(bucket: StorageBucket, path: string) {
    const { error } = await this.supabaseClient.storage
      .from(bucket)
      .remove([path]);

    if (error) {
      throw error;
    }
  }

  async upload(bucket: StorageBucket, path: string, file: Blob) {
    const { data, error } = await this.supabaseClient.storage
      .from(bucket)
      .upload(path, file);

    if (error) {
      throw error;
    }

    return data;
  }
}

export type StorageBucket = 'avatars' | 'images';
